"use client";

import React, { useEffect, useState } from "react";
import { Loader2, Plus, Edit2, Trash2 } from "lucide-react";
import { API_BASE } from "@/lib/api";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

function getAuthHeaders() {
  try {
    const user = JSON.parse(localStorage.getItem("user") || "{}");
    return {
      "x-user-id": user.id || "",
    };
  } catch {
    return { "x-user-id": "" };
  }
}

export default function BannersPage() {
  const [banners, setBanners] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [formData, setFormData] = useState({
    type: "announcement",
    headline: "",
    subheadline: "",
    badge_text: "",
    badge_color: "indigo",
    cta_text: "",
    cta_link: "",
    status: "draft",
    priority: 0
  });

  const fetchBanners = async () => {
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${API_BASE}/content/admin/banners`, { headers: getAuthHeaders() });
      const data = await res.json();
      if (data.success) {
        setBanners(data.data);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBanners();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await fetchWithAuth(`${API_BASE}/content/admin/banners`, {
        method: "POST",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });
      if (res.ok) {
        fetchBanners();
      }
    } catch (e) {
      console.error(e);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Delete banner?")) return;
    try {
      await fetchWithAuth(`${API_BASE}/content/admin/banners/${id}`, {
        method: "DELETE",
        headers: getAuthHeaders()
      });
      fetchBanners();
    } catch (e) {
      console.error(e);
    }
  };

  const toggleStatus = async (c: any) => {
    const newStatus = c.status === "active" ? "archived" : "active";
    try {
      await fetchWithAuth(`${API_BASE}/content/admin/banners/${c.id}`, {
        method: "PUT",
        headers: { ...getAuthHeaders(), "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus })
      });
      fetchBanners();
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div className="p-8 font-sans antialiased bg-app min-h-screen text-main">
      <h1 className="text-2xl font-bold mb-6">Banner Manager</h1>

      <div className="bg-card p-6 rounded-xl border border-subtle mb-8">
        <h2 className="text-lg font-semibold mb-4">Create Banner</h2>
        <form onSubmit={handleSubmit} className="flex flex-col gap-4 max-w-lg">
          <select className="bg-input border border-subtle p-2 rounded text-sm text-main" value={formData.type} onChange={e => setFormData({ ...formData, type: e.target.value })}>
            <option value="announcement">Announcement</option>
            <option value="ad">Ad</option>
            <option value="optin">Opt-in</option>
            <option value="hero">Hero</option>
          </select>
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" placeholder="Headline" value={formData.headline} onChange={e => setFormData({ ...formData, headline: e.target.value })} required />
          <textarea className="bg-input border border-subtle p-2 rounded text-sm text-main" placeholder="Subheadline" value={formData.subheadline} onChange={e => setFormData({ ...formData, subheadline: e.target.value })} />
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" placeholder="Badge Text" value={formData.badge_text} onChange={e => setFormData({ ...formData, badge_text: e.target.value })} />
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" placeholder="Badge Color (e.g., indigo, amber)" value={formData.badge_color} onChange={e => setFormData({ ...formData, badge_color: e.target.value })} />
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" placeholder="CTA Text" value={formData.cta_text} onChange={e => setFormData({ ...formData, cta_text: e.target.value })} />
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" placeholder="CTA URL" value={formData.cta_link} onChange={e => setFormData({ ...formData, cta_link: e.target.value })} />
          <select className="bg-input border border-subtle p-2 rounded text-sm text-main" value={formData.status} onChange={e => setFormData({ ...formData, status: e.target.value })}>
            <option value="draft">Draft</option>
            <option value="active">Active</option>
            <option value="archived">Archived</option>
          </select>
          <input className="bg-input border border-subtle p-2 rounded text-sm text-main" type="number" placeholder="Priority" value={formData.priority} onChange={e => setFormData({ ...formData, priority: parseInt(e.target.value) })} />
          <button type="submit" className="bg-indigo-600 hover:bg-indigo-500 text-white font-bold py-2 rounded-lg text-sm">Add Banner</button>
        </form>
      </div>

      <div className="bg-card rounded-xl border border-subtle overflow-hidden">
        {loading ? <div className="p-8 flex justify-center"><Loader2 className="animate-spin text-indigo-500" /></div> : (
          <table className="w-full text-sm text-left">
            <thead className="bg-input border-b border-subtle text-muted text-xs uppercase font-bold">
              <tr>
                <th className="px-4 py-3">Headline</th>
                <th className="px-4 py-3">Type</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3">Priority</th>
                <th className="px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody>
              {banners.map(c => (
                <tr key={c.id} className="border-b border-subtle hover:bg-input/50">
                  <td className="px-4 py-3">{c.headline}</td>
                  <td className="px-4 py-3">{c.type}</td>
                  <td className="px-4 py-3">
                    <button onClick={() => toggleStatus(c)} className={`px-2 py-1 rounded text-xs font-bold ${c.status === 'active' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'}`}>
                      {c.status}
                    </button>
                  </td>
                  <td className="px-4 py-3">{c.priority}</td>
                  <td className="px-4 py-3 flex gap-2">
                    <button onClick={() => handleDelete(c.id)} className="text-red-400 hover:text-red-300"><Trash2 size={16}/></button>
                  </td>
                </tr>
              ))}
              {banners.length === 0 && (
                <tr><td colSpan={5} className="px-4 py-6 text-center text-muted">No banners found.</td></tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
